package com.johnny.hotel.repair;import com.johnny.hotel.entity.*;import com.johnny.hotel.mapper.*;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;import java.util.stream.*;
@Component@RequiredArgsConstructor public class RepairAccess{private final SysUserMapper users;private final SysRoleMapper roles;public record Actor(Long id,Set<String> roles){boolean manager(){return roles.stream().anyMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains);}boolean finance(){return roles.contains("FINANCE");}}
 public Actor read(){var a=active();if(!a.manager()&&!a.finance()&&!a.roles().contains("STAFF"))throw denied();return a;}public Actor operate(){var a=active();if(!a.manager()&&!a.roles().contains("STAFF"))throw denied();return a;}public Actor manage(){var a=active();if(!a.manager())throw denied();return a;}private Actor active(){var auth=SecurityContextHolder.getContext().getAuthentication();if(auth==null||!auth.isAuthenticated()||!(auth.getDetails() instanceof Long id))throw denied();var u=users.selectById(id);var rs=roles.selectRolesByUserId(id).stream().map(SysRole::getRoleCode).collect(Collectors.toSet());if(u==null||!Integer.valueOf(1).equals(u.getStatus())||rs.contains("CUSTOMER")||rs.contains("HR_ADMIN"))throw denied();return new Actor(id,rs);}AccessDeniedException denied(){return new AccessDeniedException("Repair access denied");}}
